def transform(grid):
    h, w = len(grid), len(grid[0])
    # Read the motif from the only populated non-key cell.
    motif = [(r, c) for r in range(4) for c in range(4) if grid[5+r][10+c] == 1]
    out = [row[:] for row in grid]
    for br in range(0, h, 5):
        color = next((grid[br+1][c] for c in range(1,4) if grid[br+1][c] not in (0,5)), 0)
        for bc in range(0, w, 5):
            for r,c in motif:
                out[br+r][bc+c] = color
    return out
